-- =============================================================================
-- PCForge seed data. GENERATED by scripts/generate-seed.ts. Do not edit by hand:
-- change supabase/seed/data/*.ts and run `pnpm db:seed:generate`.
-- Prices, stock and history are realistic but illustrative, not live data.
-- =============================================================================

begin;

on conflict (code) do update set
  name = excluded.name,
  symbol = excluded.symbol,
  minor_units = excluded.minor_units;

on conflict (base_currency, quote_currency, valid_at) do update set
  rate = excluded.rate,
  source = excluded.source;

on conflict (code) do update set
  name = excluded.name,
  default_currency = excluded.default_currency,
  default_locale = excluded.default_locale,
  supported_locales = excluded.supported_locales,
  prices_include_tax = excluded.prices_include_tax,
  is_active = excluded.is_active,
  sort_order = excluded.sort_order;

on conflict (region_code, currency_code) do nothing;

on conflict (slug) do update set
  name = excluded.name,
  plural_name = excluded.plural_name,
  description = excluded.description,
  icon = excluded.icon,
  is_core = excluded.is_core,
  max_per_build = excluded.max_per_build,
  sort_order = excluded.sort_order;

on conflict (id) do update set
  region_code = excluded.region_code,
  category_slug = excluded.category_slug,
  name = excluded.name,
  rate = excluded.rate,
  valid_from = excluded.valid_from,
  valid_to = excluded.valid_to;

on conflict (id) do update set
  slug = excluded.slug,
  name = excluded.name,
  website_url = excluded.website_url;

on conflict (id) do update set
  slug = excluded.slug,
  name = excluded.name,
  website_url = excluded.website_url,
  search_url_template = excluded.search_url_template,
  is_marketplace = excluded.is_marketplace,
  is_active = excluded.is_active;

on conflict (retailer_id, region_code) do update set
  currency_code = excluded.currency_code,
  shipping_cost = excluded.shipping_cost,
  free_shipping_over = excluded.free_shipping_over,
  delivery_days_min = excluded.delivery_days_min,
  delivery_days_max = excluded.delivery_days_max,
  is_active = excluded.is_active;

on conflict (code) do update set
  name = excluded.name,
  description = excluded.description,
  severity = excluded.severity,
  categories = excluded.categories,
  params = excluded.params,
  is_active = excluded.is_active;

on conflict (id) do update set
  slug = excluded.slug,
  category_slug = excluded.category_slug,
  brand_id = excluded.brand_id,
  name = excluded.name,
  model = excluded.model,
  description = excluded.description,
  specs = excluded.specs,
  power_draw_w = excluded.power_draw_w,
  performance_score = excluded.performance_score,
  release_date = excluded.release_date,
  status = excluded.status;

on conflict (id) do update set
  product_id = excluded.product_id,
  sku = excluded.sku,
  mpn = excluded.mpn,
  label = excluded.label,
  specs_override = excluded.specs_override,
  is_default = excluded.is_default;

on conflict (id) do update set
  variant_id = excluded.variant_id,
  retailer_id = excluded.retailer_id,
  region_code = excluded.region_code,
  currency_code = excluded.currency_code,
  price = excluded.price,
  price_includes_tax = excluded.price_includes_tax,
  shipping_cost = excluded.shipping_cost,
  stock_status = excluded.stock_status,
  listing_type = excluded.listing_type,
  url = excluded.url,
  delivery_days_min = excluded.delivery_days_min,
  delivery_days_max = excluded.delivery_days_max,
  is_active = excluded.is_active,
  last_checked_at = excluded.last_checked_at;

-- Replace seeded history so re-running the seed does not duplicate it.
delete from public.price_history where offer_id in (select id from public.offers where last_checked_at = '2026-11-23T06:00:00.000Z') and recorded_at < '2026-11-23T06:00:00.000Z';







commit;
