  ('case', 'Case', 'Cases', 'Houses the build; limits board size, GPU length and cooler height.', 'Box', true, 1, 7),
  ('cpu-cooler', 'CPU cooler', 'CPU coolers', 'Air or liquid cooling for the processor.', 'Fan', true, 1, 8),
