insert into public.compatibility_rules (code, name, description, severity, categories, params, is_active) values
  ('cpu_motherboard.socket', 'CPU socket matches motherboard', 'The CPU must use the same socket as the motherboard.', 'error', array['cpu', 'motherboard']::text[], '{}'::jsonb, true),
  ('memory_motherboard.type', 'Memory type matches motherboard', 'DDR4 and DDR5 are not interchangeable. The memory must match the motherboard''s memory type.', 'error', array['memory', 'motherboard']::text[], '{}'::jsonb, true),
  ('memory_cpu.type', 'CPU supports memory type', 'The CPU''s memory controller must support the selected memory type.', 'error', array['memory', 'cpu']::text[], '{}'::jsonb, true),
  ('memory_motherboard.slots', 'Enough memory slots', 'The total number of memory modules cannot exceed the motherboard''s slots.', 'error', array['memory', 'motherboard']::text[], '{}'::jsonb, true),
  ('memory_motherboard.capacity', 'Memory within motherboard maximum', 'Total memory cannot exceed what the motherboard supports.', 'error', array['memory', 'motherboard']::text[], '{}'::jsonb, true),
  ('memory.speed', 'Memory speed supported', 'Memory faster than the CPU or motherboard supports will run at a lower speed unless overclocked.', 'warning', array['memory', 'motherboard', 'cpu']::text[], '{}'::jsonb, true),
  ('memory.mixed_kits', 'Matching memory kits', 'Mixing different memory kits can be unstable. Prefer a single kit.', 'warning', array['memory']::text[], '{}'::jsonb, true),
  ('motherboard_case.form_factor', 'Motherboard fits case', 'The case must support the motherboard''s form factor.', 'error', array['motherboard', 'case']::text[], '{}'::jsonb, true),
  ('gpu_case.length', 'Graphics card fits case', 'The graphics card must be shorter than the case''s maximum GPU length.', 'error', array['gpu', 'case']::text[], '{"tightClearanceMm":10}'::jsonb, true),
  ('cooler_cpu.socket', 'Cooler supports CPU socket', 'The cooler must ship with (or offer) a mounting kit for the CPU socket.', 'error', array['cpu-cooler', 'cpu']::text[], '{}'::jsonb, true),
  ('cooler_cpu.tdp', 'Cooler handles CPU heat', 'The cooler''s rated capacity should cover the CPU''s sustained power.', 'warning', array['cpu-cooler', 'cpu']::text[], '{}'::jsonb, true),
  ('cooler_case.height', 'Air cooler fits case', 'An air cooler must be shorter than the case''s maximum CPU cooler height.', 'error', array['cpu-cooler', 'case']::text[], '{}'::jsonb, true),
  ('cooler_case.radiator', 'Radiator fits case', 'A liquid cooler''s radiator size must be supported by a mounting position in the case.', 'error', array['cpu-cooler', 'case']::text[], '{}'::jsonb, true),
  ('cpu.cooler_required', 'CPU has a cooler', 'This CPU does not include a cooler, so the build needs one.', 'warning', array['cpu', 'cpu-cooler']::text[], '{}'::jsonb, true),
  ('cpu.display_output', 'Display output available', 'Without a graphics card, the CPU needs integrated graphics to show a picture.', 'error', array['cpu', 'gpu']::text[], '{}'::jsonb, true),
  ('psu.capacity', 'Power supply is strong enough', 'The power supply must deliver more than the system''s estimated peak draw.', 'error', array['psu']::text[], '{}'::jsonb, true),
  ('psu.headroom', 'Power supply headroom', 'Leave headroom for transient spikes and efficiency. Meets the GPU maker''s recommendation and a margin above peak draw.', 'warning', array['psu', 'gpu']::text[], '{"headroomRatio":0.3}'::jsonb, true),
  ('psu_gpu.connectors', 'Power supply has GPU connectors', 'The power supply should have the graphics card''s power connectors natively. Adapters work but are not ideal.', 'warning', array['psu', 'gpu']::text[], '{}'::jsonb, true),
  ('psu_motherboard.eps', 'Enough CPU power connectors', 'The power supply should provide every 8-pin EPS connector the motherboard has.', 'warning', array['psu', 'motherboard']::text[], '{}'::jsonb, true),
  ('psu_case.form_factor', 'Power supply fits case', 'The case must accept the power supply''s form factor and length.', 'error', array['psu', 'case']::text[], '{}'::jsonb, true),
  ('storage_motherboard.m2_slots', 'Enough M.2 slots', 'Each M.2 drive needs a free compatible M.2 slot.', 'error', array['storage', 'motherboard']::text[], '{}'::jsonb, true),
  ('storage_motherboard.m2_speed', 'M.2 slot runs drive at full speed', 'A drive in a slower slot works but at the slot''s speed.', 'info', array['storage', 'motherboard']::text[], '{}'::jsonb, true),
  ('storage_motherboard.sata_ports', 'Enough SATA ports', 'Each SATA drive needs a SATA port on the motherboard.', 'error', array['storage', 'motherboard']::text[], '{}'::jsonb, true),
  ('storage_case.bays', 'Enough drive bays', '2.5" and 3.5" drives need mounting bays in the case.', 'warning', array['storage', 'case']::text[], '{}'::jsonb, true),
  ('build.required_components', 'Build is complete', 'A working PC needs a CPU, motherboard, memory, storage, power supply and case.', 'info', array[]::text[], '{}'::jsonb, true)
insert into public.products (id, slug, category_slug, brand_id, name, model, description, specs, power_draw_w, performance_score, release_date, status) values
  ('f3f7c3cd-c0f5-4723-82b5-28769719993b', 'amd-ryzen-5-5600', 'cpu', 'dfec7061-8d63-40a4-bcfc-e01513e5fcca', 'AMD Ryzen 5 5600', '100-100000927BOX', 'Six-core Zen 3 processor for AM4. A budget gaming favourite that pairs with affordable DDR4 boards.', '{"socket":"AM4","architecture":"Zen 3","cores":6,"threads":12,"baseClockGhz":3.5,"boostClockGhz":4.4,"l3CacheMb":32,"tdpW":65,"maxPowerW":88,"memoryTypes":["DDR4"],"maxMemorySpeedMts":3200,"integratedGraphics":false,"coolerIncluded":true,"pcieVersion":"4.0"}'::jsonb, 76, 38, '2022-04-04', 'published'),
  ('15899d3d-ba10-4c10-85d7-8d88b5ce35d0', 'amd-ryzen-7-5700x3d', 'cpu', 'dfec7061-8d63-40a4-bcfc-e01513e5fcca', 'AMD Ryzen 7 5700X3D', '100-100001503WOF', 'Eight cores with 3D V-Cache. The strongest gaming upgrade for an existing AM4 platform.', '{"socket":"AM4","architecture":"Zen 3","cores":8,"threads":16,"baseClockGhz":3,"boostClockGhz":4.1,"l3CacheMb":96,"tdpW":105,"maxPowerW":142,"memoryTypes":["DDR4"],"maxMemorySpeedMts":3200,"integratedGraphics":false,"coolerIncluded":false,"pcieVersion":"4.0"}'::jsonb, 95, 52, '2024-01-08', 'published'),
  ('cb40b390-4f46-4c28-8b8c-c5ff2d58834b', 'amd-ryzen-5-7600', 'cpu', 'dfec7061-8d63-40a4-bcfc-e01513e5fcca', 'AMD Ryzen 5 7600', '100-100001015BOX', 'Six-core Zen 4 chip for AM5 with a bundled Wraith Stealth cooler and basic integrated graphics.', '{"socket":"AM5","architecture":"Zen 4","cores":6,"threads":12,"baseClockGhz":3.8,"boostClockGhz":5.1,"l3CacheMb":32,"tdpW":65,"maxPowerW":88,"memoryTypes":["DDR5"],"maxMemorySpeedMts":5200,"integratedGraphics":true,"coolerIncluded":true,"pcieVersion":"5.0"}'::jsonb, 80, 50, '2023-01-10', 'published'),
  ('02a1d20c-d2d5-4270-8b2c-7b1c97cc9ba3', 'amd-ryzen-5-9600x', 'cpu', 'dfec7061-8d63-40a4-bcfc-e01513e5fcca', 'AMD Ryzen 5 9600X', '100-100001405WOF', 'Six-core Zen 5 processor with strong single-thread performance at a mid-range price.', '{"socket":"AM5","architecture":"Zen 5","cores":6,"threads":12,"baseClockGhz":3.9,"boostClockGhz":5.4,"l3CacheMb":32,"tdpW":65,"maxPowerW":88,"memoryTypes":["DDR5"],"maxMemorySpeedMts":5600,"integratedGraphics":true,"coolerIncluded":false,"pcieVersion":"5.0"}'::jsonb, 82, 58, '2024-08-08', 'published'),
  ('8eef04b8-9d34-4059-8e5a-4054aca3c1cc', 'amd-ryzen-7-7800x3d', 'cpu', 'dfec7061-8d63-40a4-bcfc-e01513e5fcca', 'AMD Ryzen 7 7800X3D', '100-100000910WOF', 'Eight Zen 4 cores with 96 MB of 3D V-Cache. Excellent gaming performance at modest power.', '{"socket":"AM5","architecture":"Zen 4","cores":8,"threads":16,"baseClockGhz":4.2,"boostClockGhz":5,"l3CacheMb":96,"tdpW":120,"maxPowerW":162,"memoryTypes":["DDR5"],"maxMemorySpeedMts":5200,"integratedGraphics":true,"coolerIncluded":false,"pcieVersion":"5.0"}'::jsonb, 90, 74, '2023-04-06', 'published'),
  ('cc07b1be-0429-49b0-a97d-856d6e3f8c86', 'amd-ryzen-7-9800x3d', 'cpu', 'dfec7061-8d63-40a4-bcfc-e01513e5fcca', 'AMD Ryzen 7 9800X3D', '100-100001084WOF', 'The fastest gaming CPU of its generation, with second-generation 3D V-Cache under the cores.', '{"socket":"AM5","architecture":"Zen 5","cores":8,"threads":16,"baseClockGhz":4.7,"boostClockGhz":5.2,"l3CacheMb":96,"tdpW":120,"maxPowerW":162,"memoryTypes":["DDR5"],"maxMemorySpeedMts":5600,"integratedGraphics":true,"coolerIncluded":false,"pcieVersion":"5.0"}'::jsonb, 120, 86, '2024-11-07', 'published'),
  ('e38b172d-adc8-4414-96ac-dda339181cf2', 'amd-ryzen-9-9950x', 'cpu', 'dfec7061-8d63-40a4-bcfc-e01513e5fcca', 'AMD Ryzen 9 9950X', '100-100001277WOF', 'Sixteen Zen 5 cores for rendering, compiling and heavy multitasking.', '{"socket":"AM5","architecture":"Zen 5","cores":16,"threads":32,"baseClockGhz":4.3,"boostClockGhz":5.7,"l3CacheMb":64,"tdpW":170,"maxPowerW":230,"memoryTypes":["DDR5"],"maxMemorySpeedMts":5600,"integratedGraphics":true,"coolerIncluded":false,"pcieVersion":"5.0"}'::jsonb, 200, 92, '2024-08-15', 'published'),
  ('aff6dc84-6c5b-4ed3-94ef-0dd1ef5ed35c', 'intel-core-i5-14400f', 'cpu', '5956273f-ef71-44b2-b425-63275a7b8d90', 'Intel Core i5-14400F', 'BX8071514400F', 'Ten-core (6P + 4E) LGA1700 chip with a stock cooler. Works with both DDR4 and DDR5 boards.', '{"socket":"LGA1700","architecture":"Raptor Lake Refresh","cores":10,"threads":16,"baseClockGhz":2.5,"boostClockGhz":4.7,"l3CacheMb":20,"tdpW":65,"maxPowerW":148,"memoryTypes":["DDR4","DDR5"],"maxMemorySpeedMts":4800,"integratedGraphics":false,"coolerIncluded":true,"pcieVersion":"5.0"}'::jsonb, 110, 52, '2024-01-08', 'published'),
  ('d177c5ab-ce0e-459e-b993-830a840eb515', 'intel-core-i7-14700k', 'cpu', '5956273f-ef71-44b2-b425-63275a7b8d90', 'Intel Core i7-14700K', 'BX8071514700K', 'Twenty cores (8P + 12E), unlocked. Strong at both gaming and multi-threaded work, but power hungry.', '{"socket":"LGA1700","architecture":"Raptor Lake Refresh","cores":20,"threads":28,"baseClockGhz":3.4,"boostClockGhz":5.6,"l3CacheMb":33,"tdpW":125,"maxPowerW":253,"memoryTypes":["DDR4","DDR5"],"maxMemorySpeedMts":5600,"integratedGraphics":true,"coolerIncluded":false,"pcieVersion":"5.0"}'::jsonb, 220, 80, '2023-10-17', 'published'),
  ('b9a4f814-7288-434e-8836-b97248b516a5', 'intel-core-ultra-5-245k', 'cpu', '5956273f-ef71-44b2-b425-63275a7b8d90', 'Intel Core Ultra 5 245K', 'BX80768245K', 'Fourteen-core Arrow Lake processor on LGA1851 with efficient multi-threaded performance.', '{"socket":"LGA1851","architecture":"Arrow Lake","cores":14,"threads":14,"baseClockGhz":4.2,"boostClockGhz":5.2,"l3CacheMb":24,"tdpW":125,"maxPowerW":159,"memoryTypes":["DDR5"],"maxMemorySpeedMts":6400,"integratedGraphics":true,"coolerIncluded":false,"pcieVersion":"5.0"}'::jsonb, 140, 64, '2024-10-24', 'published'),
